// game.js - wrong-answer branch of checkAnswer() (from Step 9) now ends with startOver()
function checkAnswer(currentLevel) {
  if (gamePattern[currentLevel] === userClickedPattern[currentLevel]) {
    if (userClickedPattern.length === gamePattern.length) {
      setTimeout(function () {
        nextSequence();
      }, 1000);
    }
  } else {
    playSound("wrong");
    $("body").addClass("game-over");
    setTimeout(function () {
      $("body").removeClass("game-over");
    }, 200);
    $("#level-title").text("Game Over, Press Any Key to Restart");
    startOver();
  }
}

// Step 10: put the three state variables back to their initial values
function startOver() {
  level = 0;        // nextSequence() adds 1, so the new game shows Level 1
  gamePattern = []; // discard the old computer sequence
  started = false;  // lets the keydown/keypress handler start a new game
}
